style.css:
@keyframes moveForward {
    0% {
        transform: scale(1) translateX(0);
        opacity: 1;
    }
    50% {
        transform: scale(1.05) translateX(5px);
        opacity: 0.9;
    }
    100% {
        transform: scale(1.1) translateX(10px);
        opacity: 0.8;
    }
}

* {  /* Apply to everything, or change this to a specific class/ID */
    animation: moveForward 2s infinite alternate ease-in-out;
}
